<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requirePermission('competitors.view');$pdo=Database::connection();
function dcNormal(string $v):string{return function_exists('mb_strtolower')?mb_strtolower($v,'UTF-8'):strtolower($v);}function dcLabel(?string $v):string{return ucwords(str_replace(['_','-'],' ',(string)$v));}function dcQuery(array $c=[]):string{$q=array_merge($_GET,$c);foreach($q as $k=>$v)if($v===''||$v===null)unset($q[$k]);return'?'.http_build_query($q);}
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$style=(string)($_GET['style']??'');$level=(string)($_GET['level']??'');$event=(string)($_GET['event']??'');$category=(string)($_GET['category']??'');$complete=(string)($_GET['complete']??'');$sort=(string)($_GET['sort']??'name');$direction=strtolower((string)($_GET['order']??'asc'))==='desc'?'desc':'asc';$perPage=in_array((int)($_GET['per_page']??50),[25,50,100,200,500],true)?(int)$_GET['per_page']:50;$page=max(1,(int)($_GET['page']??1));
// Keep the core read identical to the query proven through the Production signed API.
$sql="SELECT w.id,w.identity_code,w.entry_type,w.display_name,w.country,w.solo_competitor_id,w.photo_url,c.photo_url shared_photo,COUNT(r.id) registration_count,GROUP_CONCAT(CONCAT(r.event_key,':',r.category_key) ORDER BY r.event_key,r.category_key SEPARATOR ',') registrations FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id LEFT JOIN bdc_wdc_registrations r ON r.wdc_identity_id=w.id AND r.status='registered' WHERE w.status='active' GROUP BY w.id,w.identity_code,w.entry_type,w.display_name,w.country,w.solo_competitor_id,w.photo_url,c.photo_url ORDER BY LOWER(w.display_name),w.id LIMIT 500";
$allRows=$pdo->query($sql)->fetchAll();$registrationMap=[];$eventOptions=[];$categoryOptions=[];
// Optional enrichment is isolated so a summary-table problem can never blank the directory again.
try{$registrationRows=$pdo->query("SELECT wdc_identity_id,event_key,event_name,category_key,category_name,dance_style,competition_level FROM bdc_wdc_registrations WHERE status='registered' ORDER BY event_name,category_name,id")->fetchAll();foreach($registrationRows as $r){$registrationMap[(int)$r['wdc_identity_id']][]=$r;$eventOptions[(string)$r['event_key']]=(string)$r['event_name'];$categoryOptions[(string)$r['category_key']]=(string)$r['category_name'];}}catch(Throwable $ignored){}
$pointMap=[];$resultMap=[];try{foreach($pdo->query('SELECT wdc_identity_id,SUM(points) points,COUNT(*) entries FROM bdc_wdc_championship_points GROUP BY wdc_identity_id')->fetchAll() as $r)$pointMap[(int)$r['wdc_identity_id']]=$r;}catch(Throwable $ignored){}try{foreach($pdo->query('SELECT wdc_identity_id,COUNT(*) entries FROM bdc_dance_cup_result_history WHERE wdc_identity_id IS NOT NULL GROUP BY wdc_identity_id')->fetchAll() as $r)$resultMap[(int)$r['wdc_identity_id']]=(int)$r['entries'];}catch(Throwable $ignored){}
$duplicateNames=[];foreach($allRows as $r){$key=$r['entry_type'].'|'.dcNormal(trim((string)$r['display_name']));$duplicateNames[$key]=($duplicateNames[$key]??0)+1;}foreach($allRows as &$r){$id=(int)$r['id'];$r['registration_rows']=$registrationMap[$id]??[];$r['photo_display']=$r['photo_url']?:$r['shared_photo'];$r['points']=(float)($pointMap[$id]['points']??0);$r['published_entries']=max((int)($pointMap[$id]['entries']??0),(int)($resultMap[$id]??0));$key=$r['entry_type'].'|'.dcNormal(trim((string)$r['display_name']));$r['duplicate_count']=max(0,($duplicateNames[$key]??1)-1);}unset($r);
$counts=['WDC identities'=>count($allRows),'Active registrations'=>array_sum(array_map(static fn(array $r):int=>(int)$r['registration_count'],$allRows)),'Bachata entries'=>0,'Salsa entries'=>0,'Missing photos'=>0,'Possible duplicates'=>0];foreach($allRows as $r){if(trim((string)$r['photo_display'])==='')$counts['Missing photos']++;if((int)$r['duplicate_count'])$counts['Possible duplicates']++;foreach($r['registration_rows'] as $reg){if(dcNormal((string)$reg['dance_style'])==='bachata')$counts['Bachata entries']++;if(dcNormal((string)$reg['dance_style'])==='salsa')$counts['Salsa entries']++;}}
$rows=array_values(array_filter($allRows,static function(array $r)use($q,$type,$style,$level,$event,$category,$complete):bool{$details=[];foreach($r['registration_rows'] as $reg)$details[]=implode(' ',array_map('strval',$reg));$haystack=dcNormal(implode(' ',[$r['display_name'],$r['identity_code'],$r['country'],$r['registrations'],implode(' ',$details)]));if($q!==''&&!str_contains($haystack,dcNormal($q)))return false;if($type!==''&&$r['entry_type']!==$type)return false;if($complete==='missing_photo'&&trim((string)$r['photo_display'])!=='')return false;if($complete==='missing_country'&&trim((string)$r['country'])!=='')return false;if($complete==='no_registration'&&(int)$r['registration_count']>0)return false;if($complete==='duplicate'&&(int)$r['duplicate_count']===0)return false;if($style!==''&&!array_filter($r['registration_rows'],static fn(array $x):bool=>$x['dance_style']===$style))return false;if($level!==''&&!array_filter($r['registration_rows'],static fn(array $x):bool=>$x['competition_level']===$level))return false;if($event!==''&&!array_filter($r['registration_rows'],static fn(array $x):bool=>$x['event_key']===$event))return false;if($category!==''&&!array_filter($r['registration_rows'],static fn(array $x):bool=>$x['category_key']===$category))return false;return true;}));
$sorters=['name'=>static fn(array $r):string=>dcNormal((string)$r['display_name']),'wdc_id'=>static fn(array $r):string=>(string)$r['identity_code'],'country'=>static fn(array $r):string=>dcNormal((string)$r['country']),'type'=>static fn(array $r):string=>(string)$r['entry_type'],'entries'=>static fn(array $r):int=>(int)$r['registration_count'],'points'=>static fn(array $r):float=>(float)$r['points']];$sort=array_key_exists($sort,$sorters)?$sort:'name';usort($rows,static function(array $a,array $b)use($sorters,$sort,$direction):int{$n=$sorters[$sort]($a)<=>$sorters[$sort]($b);return$direction==='desc'?-$n:$n;});
if(($_GET['export']??'')==='csv'){Auth::requireSuperAdmin();header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="wdc-competitors-'.date('Y-m-d-His').'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['WDC ID','Name','Entry Type','Country','Registrations','Points','Published Results']);foreach($rows as $r)fputcsv($out,[$r['identity_code'],$r['display_name'],$r['entry_type'],$r['country'],implode(' | ',array_map(static fn(array $x):string=>$x['event_name'].' - '.$x['category_name'],$r['registration_rows'])),$r['points'],$r['published_entries']]);fclose($out);exit;}
$total=count($rows);$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$rows=array_slice($rows,$offset,$perPage);asort($eventOptions,SORT_NATURAL|SORT_FLAG_CASE);asort($categoryOptions,SORT_NATURAL|SORT_FLAG_CASE);$sortUrl=static fn(string $column):string=>dcQuery(['sort'=>$column,'order'=>$sort===$column&&$direction==='asc'?'desc':'asc','page'=>1]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Competitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:1rem}.photo{width:58px;height:68px;object-fit:cover;border-radius:10px;border:1px solid #dce3ec}.registration{border-left:3px solid #0d6efd;padding-left:.55rem;margin:.35rem 0;min-width:260px}.actions{display:flex;gap:.35rem;flex-wrap:wrap}.sortable{color:inherit;text-decoration:none}@media(max-width:767px){.actions{display:grid}.actions .btn{width:100%}}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="<?=e(url('admin/'))?>">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="<?=e(url('admin/dance-cup/'))?>">Dance Cup Scoring</a></div></nav><main class="container-fluid py-4" style="max-width:1700px"><div class="d-flex justify-content-between gap-3 flex-wrap mb-3"><div><h1 class="h3 mb-1">Dance Cup Competitor</h1><p class="text-muted mb-0">One permanent WDC identity with registrations, results and profile actions.</p></div><div class="d-flex gap-2"><?php if(Auth::isSuperAdmin()):?><a class="btn btn-outline-success" href="<?=e(dcQuery(['export'=>'csv','page'=>null]))?>">Export CSV</a><a class="btn btn-outline-warning" href="<?=e(dcQuery(['complete'=>'duplicate','page'=>1]))?>">Review duplicates</a><?php endif;?><?php if(Auth::can('competitors.edit')):?><a class="btn btn-dark" href="competitor-edit.php">Add competitor</a><?php endif;?></div></div><section class="summary mb-4"><?php foreach($counts as $title=>$value):$target=$title==='Missing photos'?dcQuery(['complete'=>'missing_photo','page'=>1]):($title==='Possible duplicates'?dcQuery(['complete'=>'duplicate','page'=>1]):'#');?><a class="card border-0 shadow-sm text-decoration-none text-dark" href="<?=e($target)?>"><div class="card-body"><div class="small text-muted"><?=e($title)?></div><strong class="fs-2"><?=$value?></strong></div></a><?php endforeach;?></section>
<form class="card border-0 shadow-sm mb-3"><div class="card-body row g-2"><div class="col-xl-4"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, WDC ID, country, event or category"></div><?php foreach(['type'=>['Entry type',[''=>'All types','solo'=>'Solo','couple'=>'Couple','duo'=>'Duo','pro_am'=>'Pro Am','team'=>'Team']], 'style'=>['Dance style',[''=>'All styles','bachata'=>'Bachata','salsa'=>'Salsa']], 'level'=>['Level',[''=>'All levels','open'=>'Open','amateur'=>'Amateur','intermediate'=>'Intermediate','pro_am'=>'Pro Am','professional'=>'Professional']], 'complete'=>['Completeness',[''=>'Any','missing_photo'=>'Missing photo','missing_country'=>'Missing country','no_registration'=>'No registration','duplicate'=>'Possible duplicate']]] as $field=>[$label,$options]):?><div class="col-6 col-xl"><label class="form-label"><?=e($label)?></label><select class="form-select" name="<?=$field?>"><?php foreach($options as $value=>$text):?><option value="<?=e($value)?>" <?=($$field===$value)?'selected':''?>><?=e($text)?></option><?php endforeach;?></select></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Event</label><select class="form-select" name="event"><option value="">All events</option><?php foreach($eventOptions as $key=>$name):?><option value="<?=e($key)?>" <?=$event===$key?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Category</label><select class="form-select" name="category"><option value="">All categories</option><?php foreach($categoryOptions as $key=>$name):?><option value="<?=e($key)?>" <?=$category===$key?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div class="col-12 d-flex gap-2"><button class="btn btn-dark">Apply filters</button><a class="btn btn-outline-secondary" href="competitors.php">Reset</a></div></div></form>
<div class="d-flex justify-content-between small text-muted mb-2"><span>Showing <?=$total?$offset+1:0?> to <?=min($offset+$perPage,$total)?> of <?=$total?> identities</span><span>Click a column heading to sort</span></div><section class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Photo</th><?php foreach(['wdc_id'=>'WDC ID','name'=>'Participant','country'=>'Country','type'=>'Entry Type','entries'=>'Registrations','points'=>'Points / Results'] as $column=>$title):?><th><a class="sortable" href="<?=e($sortUrl($column))?>"><?=e($title)?></a></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr id="wdc-<?=(int)$r['id']?>"><td><img class="photo" src="<?=e($r['photo_display']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></td><td><code><?=e($r['identity_code'])?></code><?php if((int)$r['duplicate_count']):?><span class="badge text-bg-warning d-block mt-1">Possible duplicate</span><?php endif;?></td><td><strong><?=e($r['display_name'])?></strong></td><td><?=e($r['country']?:'—')?></td><td><?=e(dcLabel($r['entry_type']))?></td><td><?php foreach($r['registration_rows'] as $reg):?><div class="registration"><strong><?=e($reg['category_name'])?></strong><small class="d-block text-muted"><?=e($reg['event_name'])?> · <?=e(dcLabel($reg['dance_style']))?> · <?=e(dcLabel($reg['competition_level']))?></small></div><?php endforeach;?><?php if(!$r['registration_rows']):?><?php foreach(array_filter(explode(',',(string)$r['registrations'])) as $reg):?><div class="registration"><?=e(dcLabel(str_replace(':',' · ',$reg)))?></div><?php endforeach;?><?php endif;?><?php if(!(int)$r['registration_count']):?><span class="text-muted">No active registration</span><?php endif;?></td><td><strong><?=e((string)$r['points'])?> pts</strong><small class="d-block text-muted"><?=(int)$r['published_entries']?> published result(s)</small></td><td><div class="actions"><?php if(Auth::can('competitors.edit')):?><a class="btn btn-sm btn-dark" href="competitor-edit.php?id=<?=(int)$r['id']?>">Edit WDC</a><a class="btn btn-sm btn-outline-primary" href="photo-adjust.php?id=<?=(int)$r['id']?>">Adjust photo</a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-5">No Dance Cup competitors match the selected filters.</td></tr><?php endif;?></tbody></table></div></section><?php if($pages>1):?><nav class="mt-3"><ul class="pagination flex-wrap"><?php for($n=1;$n<=$pages;$n++):?><li class="page-item <?=$n===$page?'active':''?>"><a class="page-link" href="<?=e(dcQuery(['page'=>$n]))?>"><?=$n?></a></li><?php endfor;?></ul></nav><?php endif;?></main></body></html>
